// ESM bundles generated by esbuild may dynamically require Node built-ins.
// Keep the exact runner self-contained and refuse any non-built-in lookup.
export const builtinOnlyRequireBanner = `import { builtinModules as __runnerBuiltinModules, createRequire as __runnerCreateRequire } from "node:module";
const __runnerNativeRequire = __runnerCreateRequire(import.meta.url);
const __runnerAllowedBuiltins = new Set(__runnerBuiltinModules.flatMap((name) =>
  [name, name.startsWith("node:") ? name.slice(5) : \`node:\${name}\`]));
const require = (name) => {
  if (typeof name !== "string" || !__runnerAllowedBuiltins.has(name)) {
    throw new Error("owner_runner_non_builtin_require_refused");
  }
  return __runnerNativeRequire(name);
};`;
